            reportDate: reportDate,
            reportType: KIND_TITLES.wanted,
            supplementNo: '',
            agencyName: 'Fort Worth Police Department',
            location: location,
            beat: '',
            fromDateTime: '',
            toDateTime: '',
            offenses: offenses,
            personsInvolved: people,
            provisionalPersons: [],
            vehicles: [],
            property: [],
            narratives: [],
            digital: [],
            confidentialPersons: [],
            pageCount: doc.pages.length,
            rawText: raw,
